class ConflictError(ValueError): pass
class Inventory:
    def __init__(self, stocks):
        self.stocks = dict(stocks)  # {(tenant, sku): quantity}
        self.requests = {}
    def reserve(self, tenant, request_id, items):
        if request_id in self.requests:
            return self.requests[request_id]
        for sku, quantity in items:
            self.stocks[(tenant, sku)] -= quantity
        receipt = {"items": dict(items), "status": "reserved"}
        self.requests[request_id] = receipt
        return receipt
    def release(self, tenant, request_id):
        receipt = self.requests[request_id]
        for sku, quantity in receipt["items"].items():
            self.stocks[(tenant, sku)] += quantity
        receipt["status"] = "released"
        return receipt

